[{"order":1,"type":"heading","text":"Mastering Rendering Strategies in Next.js App Router"},{"order":2,"type":"paragraph","text":"The Next.js App Router fundamentally changes how developers approach web architecture by blending Static Site Generation (SSG), Incremental Static Regeneration (ISR), and Server-Side Rendering (SSR) into a unified, component-based model. Understanding when and how to apply each strategy is critical for building performant, scalable web applications."},{"order":3,"type":"subheading","text":"1. Static Site Generation (SSG)"},{"order":4,"type":"paragraph","text":"SSG is the default rendering strategy in the Next.js App Router. Pages are pre-rendered at build time. The resulting HTML is reused on each request, making SSG ideal for marketing pages, blogs, and documentation where content changes infrequently."},{"order":5,"type":"code","text":"// app/blog/[slug]/page.tsx
// By default, components in the App Router are static if no dynamic functions are used.

export async function generateStaticParams() {
  const posts = await fetch('https://api.example.com/posts').then((res) => res.json());

  return posts.map((post: { slug: string }) => ({
    slug: post.slug,
  }));
}

export default async function BlogPost({ params }: { params: { slug: string } }) {
  const res = await fetch(`https://api.example.com/posts/${params.slug}`);
  const post = await res.json();

  return (
    <article>
      <h1>{post.title}</h1>
      <p>{post.content}</p>
    </article>
  );
}"},{"order":6,"type":"subheading","text":"2. Incremental Static Regeneration (ISR)"},{"order":7,"type":"paragraph","text":"ISR enables you to update static pages after you have built your site without needing to rebuild the entire application. By specifying a revalidation time, Next.js will background-regenerate the page when a request comes in."},{"order":8,"type":"code","text":"// app/products/[id]/page.tsx

// Revalidate this page every 60 seconds
export const revalidate = 60;

export async function generateStaticParams() {
  return [{ id: '1' }, { id: '2' }];
}

export default async function ProductPage({ params }: { params: { id: string } }) {
  const res = await fetch(`https://api.example.com/products/${params.id}`);
  const product = await res.json();

  return (
    <div>
      <h1>{product.name}</h1>
      <p>Price: ${product.price}</p>
    </div>
  );
}"},{"order":9,"type":"subheading","text":"3. Server-Side Rendering (SSR)"},{"order":10,"type":"paragraph","text":"SSR dynamically renders pages on every incoming request. This strategy is best suited for highly personalized data, real-time dashboards, or content that relies heavily on request headers like cookies or query parameters."},{"order":11,"type":"code","text":"// app/dashboard/page.tsx
import { cookies } from 'next/headers';

export default async function DashboardPage() {
  const cookieStore = cookies();
  const token = cookieStore.get('token');

  // Forcing dynamic rendering by using request-specific data
  const res = await fetch('https://api.example.com/user-data', {
    headers: {
      Authorization: `Bearer ${token?.value}`,
    },
    cache: 'no-store',
  });
  const data = await res.json();

  return (
    <div>
      <h1>User Dashboard</h1>
      <p>Welcome back, {data.username}</p>
    </div>
  );
}"},{"order":12,"type":"subheading","text":"Summary of Best Practices"},{"order":13,"type":"bullet_point","text":"Use SSG for static content that rarely changes to maximize speed and minimize server load."},{"order":14,"type":"bullet_point","text":"Use ISR for large catalogs or database-driven sites where eventual consistency is acceptable."},{"order":15,"type":"bullet_point","text":"Use SSR sparingly, strictly reserving it for pages that require real-time user-specific personalization or request headers."}]
